<?php
declare(strict_types=1);require __DIR__.'/config.php';require_login();require __DIR__.'/patient-layout.php';$pdo=db();
$invoices=$pdo->query('SELECT MAX(m.invoice_no) invoice_no,m.movement_type,MIN(m.movement_date) movement_date,MAX(c.code) account_code,MAX(COALESCE(c.short_name,c.title)) account_name,COUNT(*) line_count,SUM(COALESCE(m.purchase_price,0)) total FROM stock_movements m LEFT JOIN current_accounts c ON c.id=m.current_account_id WHERE TRIM(COALESCE(m.invoice_no,""))<>"" GROUP BY LOWER(TRIM(m.invoice_no)),m.movement_type ORDER BY MIN(m.movement_date) DESC,MAX(m.id) DESC')->fetchAll();patient_header('Fatura Listesi','stock');?>
<main class="patient-container inv-list"><section><header><div><h1>Fatura Listesi</h1><p>Stok giriş ve çıkış faturaları.</p></div><a href="<?=e(url('invoice-entry.php'))?>">Fatura Girişi</a></header><?php if(isset($_GET['saved'])):?><p class="notice">Fatura kaydedildi.</p><?php endif?><div class="wrap"><table><thead><tr><th>FATURA NO</th><th>TARİH</th><th>HAREKET YÖNÜ</th><th>CARİ</th><th>KALEM</th><th>ALIŞ TOPLAMI</th><th>İŞLEM</th></tr></thead><tbody><?php foreach($invoices as $invoice):?><tr><td><?=e($invoice['invoice_no'])?></td><td><?=e(format_date_tr($invoice['movement_date']))?></td><td><b class="<?=$invoice['movement_type']==='Giriş'?'in':'out'?>"><?=e($invoice['movement_type'])?></b></td><td><?=e(trim(($invoice['account_code']?$invoice['account_code'].' — ':'').$invoice['account_name']))?></td><td><?=$invoice['line_count']?></td><td><?=e(number_format((float)$invoice['total'],2,',','.'))?> TL</td><td><?php if($invoice['movement_type']==='Giriş'):?><a class="edit" href="<?=e(url('invoice-entry.php?edit_invoice='.rawurlencode((string)$invoice['invoice_no'])))?>">Düzenle</a><?php else:?>—<?php endif?></td></tr><?php endforeach;if(!$invoices):?><tr><td colspan="7">Henüz fatura bulunmuyor.</td></tr><?php endif?></tbody></table></div></section></main><style>.inv-list{max-width:1500px;margin:30px auto;padding:0 18px}.inv-list section{border:1px solid #e1e2e8;border-radius:10px;background:#fff;overflow:hidden}.inv-list header{display:flex;align-items:center;gap:18px;padding:22px 24px;border-bottom:1px solid #e1e2e8}.inv-list header>a{margin-left:auto;padding:10px 15px;border-radius:7px;background:#19a94b;color:#fff;text-decoration:none;font-weight:600}.inv-list h1{margin:0 0 5px}.inv-list p{margin:0;color:#7b7b8d}.notice{margin:14px 24px!important;padding:10px;background:#dff6e6;color:#147736!important}.wrap{overflow:auto}.inv-list table{width:100%;min-width:1000px;border-collapse:collapse}.inv-list th,.inv-list td{padding:14px 18px;border-bottom:1px solid #e1e2e8;text-align:left}.inv-list th{font-size:12px}.in{color:#e04f55}.out{color:#19a94b}.edit{color:#19a94b;text-decoration:none;font-weight:600}</style><?php patient_footer();
